mapper.select:
SELECT id,capsule_id,revision_no,content_format,content,content_hash,change_reason,create_time
FROM ai_capsule_revision WHERE tenant_id=#{tenantId} AND owner_user_id=#{ownerUserId} AND owner_subject_type=#{subjectType} AND capsule_id=#{capsuleId}
AND revision_no < #{beforeRevision}
ORDER BY revision_no DESC LIMIT #{limit}
